#!/usr/bin/env python3
from pathlib import Path
import shutil, sys
ROOT=Path(__file__).resolve().parent
APP=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path.cwd()
REPO=APP/"app/modules/engagement/repositories.py"
API=APP/"app/modules/engagement/api.py"
MOD=APP/"app/modules/engagement/system_questionnaire.py"
UPDATE_SYSTEM_ITEM='def update_system_item(item_id, results, observation, info_exception, auto_score, user, source="ONLINE"):\n    x("UPDATE engagement.items SET results = CAST(:r AS jsonb), observation = :o, info_exception = :e, auto_score = :a, source = :s, updated_by = CAST(:u AS uuid), updated_at = now() WHERE id = CAST(:i AS uuid)",\n      r=json.dumps(results), o=observation, e=info_exception, a=auto_score, s=source, u=user, i=str(item_id))\n    x("UPDATE engagement.worksheets SET updated_at = now() WHERE id = (SELECT worksheet_id FROM engagement.items WHERE id = CAST(:i AS uuid))", i=str(item_id))\n\n'
REPLACE_SYSTEM_QUESTIONNAIRE='def replace_system_questionnaire(worksheet_id, criteria, user, title=None):\n    """Reconfigura una cédula de Sistemas con un cuestionario importado.\n\n    Solo se permite cuando la cédula no tiene respuestas, observaciones ni\n    evidencias asociadas a sus ítems. Así se evita destruir información de\n    auditoría. Los controles importados pasan a ser la base real de la cédula;\n    los controles adicionales se agregan después manualmente.\n    """\n    ws_id = str(worksheet_id)\n    existing = q("SELECT id::text, results, observation, info_exception, manual_score, manual_reason "\n                 "FROM engagement.items WHERE worksheet_id = CAST(:w AS uuid)", w=ws_id)\n    if any((r.get("results") or {}) or r.get("observation") or r.get("info_exception") or r.get("manual_score") is not None\n           or r.get("manual_reason") for r in existing):\n        raise ValueError("La cédula ya contiene respuestas o ajustes; no se puede reemplazar su estructura mediante Excel")\n    evidence = q1("SELECT id::text FROM engagement.evidence WHERE item_id IN "\n                   "(SELECT id FROM engagement.items WHERE worksheet_id = CAST(:w AS uuid)) LIMIT 1", w=ws_id)\n    observations = q1("SELECT id::text FROM engagement.observations WHERE item_id IN "\n                      "(SELECT id FROM engagement.items WHERE worksheet_id = CAST(:w AS uuid)) LIMIT 1", w=ws_id)\n    if evidence or observations:\n        raise ValueError("La cédula ya tiene evidencias u observaciones; no se puede reemplazar su estructura mediante Excel")\n\n    # Los ítems están vacíos, por lo que es seguro recrearlos con los controles\n    # reales del archivo recibido.\n    x("DELETE FROM engagement.items WHERE worksheet_id = CAST(:w AS uuid)", w=ws_id)\n    x("UPDATE engagement.worksheets SET criteria = CAST(:c AS jsonb), template_version = template_version + 1, "\n      "title = COALESCE(:t, title), updated_at = now() WHERE id = CAST(:w AS uuid)",\n      c=json.dumps(criteria, ensure_ascii=False), t=title, w=ws_id)\n    for c in criteria:\n        x("INSERT INTO engagement.items (id, worksheet_id, ref, source, updated_by) "\n          "VALUES (CAST(:i AS uuid), CAST(:w AS uuid), :r, \'ONLINE\', CAST(:u AS uuid)) "\n          "ON CONFLICT (worksheet_id, ref) DO NOTHING",\n          i=str(uuid.uuid4()), w=ws_id, r=c["code"], u=user)\n    db.session.commit()\n\n'
SYSTEM_ROUTE='@bp.post("/worksheets/<uuid:wid>/system-questionnaire/import")\n@permission_required("audit:manage", "audit:systems_execute")\ndef import_system_questionnaire(wid):\n    ws, a, e = ws_for(wid, write=True)\n    if e:\n        return e\n    if ws["kind"] != "SISTEMAS" or a.get("audit_domain") != "SISTEMAS":\n        return err("La importación del cuestionario solo está disponible para Auditoría de Sistemas", 403)\n    f = request.files.get("file")\n    if f is None:\n        return err("Adjunte el cuestionario Excel")\n    data = f.read(system_questionnaire.MAX_BYTES + 1)\n    try:\n        name, ctype = evidence_rules.check(f.filename, data)\n        if not name.lower().endswith(".xlsx"):\n            return err("El cuestionario debe ser un archivo .xlsx")\n        parsed = system_questionnaire.parse(data)\n    except (ValueError, evidence_rules.EvidenceError) as ex:\n        return err(str(ex))\n\n    if parsed["questionnaire_type"] == "ERP_TI":\n        items = {i["ref"]: i for i in ws["items"]}\n        criteria = {c["code"]: c for c in ws["criteria"]}\n        if len(items) != 81 or set(items) != set(criteria):\n            return err("La cédula ERP/TI no tiene los 81 controles oficiales. Cree una cédula ERP/TI nueva.", 409)\n        for row in parsed["rows"]:\n            ref = row["ref"]\n            if ref not in items:\n                return err(f"Control no reconocido: {ref}", 400)\n            result = {"control": row["control"], "documental": row["documental"], "evidencia": row["evidencia"]}\n            auto = scoring.item_score(ws["criteria"], {ref: result})\n            repo.update_system_item(items[ref]["id"], {ref: result}, row["observation"], None, auto, me(), source="ONLINE")\n        imported_count = parsed["controls"]\n    else:\n        # Seguridad de TI es un cuestionario distinto al ERP/TI. No se hace\n        # correspondencia por posición ni por aproximación de texto: se cargan\n        # exactamente los controles presentes en el Excel.\n        criteria = [\n            {\n                "code": row["ref"],\n                "text": row["question"],\n                "weight": 1,\n                "source_id": row["source_id"],\n                "section": row["section"],\n                "evaluation_mode": "SEC_TI",\n            }\n            for row in parsed["rows"]\n        ]\n        try:\n            repo.replace_system_questionnaire(\n                wid,\n                criteria,\n                me(),\n                title="Auditoría de Sistemas — Seguridad de TI",\n            )\n        except ValueError as ex:\n            return err(str(ex), 409)\n        fresh_after_replace = repo.get_worksheet(wid)\n        items = {i["ref"]: i for i in fresh_after_replace["items"]}\n        for row in parsed["rows"]:\n            ref = row["ref"]\n            result = {"control": row["control"], "documental": row["documental"], "evidencia": row["evidencia"]}\n            auto = scoring.item_score(fresh_after_replace["criteria"], {ref: result})\n            repo.update_system_item(items[ref]["id"], {ref: result}, row["observation"], None, auto, me(), source="ONLINE")\n        imported_count = parsed["controls"]\n\n    sha = hashlib.sha256(data).hexdigest()\n    key = f"evidence/{a[\'id\']}/{uuid.uuid4()}"\n    try:\n        storage.put(key, data)\n        eid = repo.add_evidence(a["id"], None, None, name, ctype, len(data), sha, key,\n                                "Cuestionario de Auditoría de Sistemas utilizado para cargar la auditoría", me())\n    except Exception as ex:  # noqa: BLE001\n        repo.db.session.rollback()\n        return err("El cuestionario fue procesado, pero no fue posible conservar el Excel como evidencia", 500)\n\n    fresh = repo.get_worksheet(wid)\n    stats = scoring.system_statistics(fresh["criteria"], fresh["items"])\n    log("SYSTEM_QUESTIONNAIRE_IMPORTED", entity_type="worksheet", entity_id=wid,\n        after_data={"tipo": parsed["questionnaire_type"], "controles": imported_count, "evidence_id": eid, "sha256": sha, **stats},\n        request_id=g.request_id)\n    return jsonify(imported=True, questionnaire_type=parsed["questionnaire_type"], evidence_id=eid, sha256=sha,\n                   statistics=stats)\n\n\n@bp.post("/worksheets/<uuid:wid>/system-controls")\n@permission_required("audit:manage")\ndef add_system_control(wid):\n    ws, a, e = ws_for(wid, write=True)\n    if e:\n        return e\n    if ws["kind"] != "SISTEMAS" or a.get("audit_domain") != "SISTEMAS":\n        return err("El control manual solo está disponible para Auditoría de Sistemas", 403)\n    d = request.get_json(silent=True) or {}\n    text = str(d.get("text") or "").strip()\n    section = str(d.get("section") or "Seguridad de TI").strip()\n    try:\n        weight = int(d.get("weight", 1))\n    except (TypeError, ValueError):\n        weight = 1\n    if not 5 <= len(text) <= 300:\n        return err("El texto del control debe tener entre 5 y 300 caracteres")\n    if not 1 <= len(section) <= 150:\n        return err("La sección del control no es válida")\n    if weight not in (1, 2, 3):\n        return err("El peso debe ser 1, 2 o 3")\n    try:\n        code = repo.add_system_control(wid, text, section, weight, me())\n    except ValueError as ex:\n        return err(str(ex), 409)\n    log("SYSTEM_CONTROL_ADDED", entity_type="worksheet", entity_id=wid,\n        after_data={"code": code, "section": section, "weight": weight}, request_id=g.request_id)\n    return jsonify(code=code), 201\n\n'
def backup(p):
    b=p.with_suffix(p.suffix+".pre_cuestionario_sistemas.bak")
    if p.exists() and not b.exists(): shutil.copy2(p,b)
def insert_before(text, marker, block):
    if block.strip() in text: return text
    i=text.find(marker)
    if i<0: raise RuntimeError(f"No se encontró ancla: {marker}")
    return text[:i]+block+"\n"+text[i:]
for p in (REPO,API):
    if not p.exists(): raise RuntimeError(f"No existe {p}")
    backup(p)
MOD.parent.mkdir(parents=True,exist_ok=True)
shutil.copy2(ROOT/"system_questionnaire.py",MOD)
repo=REPO.read_text()
if "def update_system_item(" not in repo: repo=insert_before(repo,"WS_SQL = (",UPDATE_SYSTEM_ITEM)
if "def replace_system_questionnaire(" not in repo: repo=insert_before(repo,"WS_SQL = (",REPLACE_SYSTEM_QUESTIONNAIRE)
REPO.write_text(repo)
api=API.read_text()
if "from . import evidence_rules, offline, scoring, storage, system_questionnaire" not in api:
    api=api.replace("from . import evidence_rules, offline, scoring, storage\n","from . import evidence_rules, offline, scoring, storage, system_questionnaire\n",1)
if "/system-questionnaire/import" not in api: api=insert_before(api,'@bp.post("/worksheets/<uuid:wid>/items")',SYSTEM_ROUTE)
API.write_text(api)
print("OK: restauración aislada del cuestionario de Sistemas aplicada")
print("No se modifica pages_audit.js, scoring.py, SQL, roles, navegación ni flujo de autorización")
